            else if (method == "set_unstable_period") {
                int id = GetInt(p, "id", -1);
                int period = GetInt(p, "period", 0);
                if (period < 0 || period > Core.MAX_INDEX) {
                    return "{\"error\":\"Invalid unstable period value\"}";
                }
                if (id == (int)FuncUnstId.ALL) {
                    for (int i = 0; i < core.unstablePeriod.Length; i++) core.unstablePeriod[i] = period;
                    return "{\"status\":\"ok\"}";
                }
                if (id >= 0 && id < core.unstablePeriod.Length) {
                    core.unstablePeriod[id] = period;
                    return "{\"status\":\"ok\"}";
                }
                return "{\"error\":\"Invalid id\"}";
            }
            else if (method == "set_compatibility") {
                int mode = GetInt(p, "mode", 0);
                if (mode == 0) {
                    return "{\"status\":\"ok\"}";
                }
                return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
            }
            else if (method == "set_candle_settings") {
                int settingType = GetInt(p, "settingType", -1);
                int rangeType = GetInt(p, "rangeType", -1);
                int avgPeriod = GetInt(p, "avgPeriod", 0);
                double factor = GetF64Bits(p, "factorBits", 1.0);
                try {
                    core = core.ToBuilder()
                        .CandleSetting((CandleSettingType)settingType, (RangeType)rangeType,
                                       avgPeriod, factor)
                        .Build();
                } catch (ArgumentOutOfRangeException) {
                    return "{\"error\":\"Invalid candle setting\"}";
                }
                return "{\"status\":\"ok\"}";
            }
            else if (method == "restore_candle_default_settings") {
                int settingType = GetInt(p, "settingType", -1);
                try {
                    core = core.ToBuilder()
                        .RestoreCandleDefault((CandleSettingType)settingType)
                        .Build();
                } catch (ArgumentOutOfRangeException) {
                    return "{\"error\":\"Invalid candle setting type\"}";
                }
                return "{\"status\":\"ok\"}";
            }
            else if (method == "eval_predicate") {
                int which = GetInt(p, "which", 0);
                double[] values = GetDoubleArray(p, "values");
                double[] scale = GetDoubleArray(p, "scale");
                var parts = new string[values.Length];
                for (int i = 0; i < values.Length; i++) {
                    double v = values[i];
                    double sc = (i < scale.Length) ? scale[i] : 0.0;
                    bool r;
                    if (which == 1) r = (Math.Abs(v) <= 0.00000000000001 * (sc));
                    else if (which == 2) r = (v < 0.00000000000001);
                    else r = ((-0.00000000000001 < v) && (v < 0.00000000000001));
                    parts[i] = r ? "1" : "0";
                }
                return "{\"outInteger\":[" + string.Join(",", parts) + "]}";
            }
            else if (method == "abstract_get_lookback") {
                string fn = p.GetProperty("funcName").GetString()!;
                return $"{{\"lookback\":{ComputeLookback(fn, p)}}}";
            }
            else if (method == "TA_GetFuncInfo") return AbsFuncInfo(p);
            else if (method == "TA_GetInputParameterInfo") return AbsInputInfo(p);
            else if (method == "TA_GetOptInputParameterInfo") return AbsOptInputInfo(p);
            else if (method == "TA_GetOutputParameterInfo") return AbsOutputInfo(p);
            else if (method == "abstract_for_each_func") return AbsForEachFunc();
            else if (method == "TA_FunctionDescriptionXML") return AbsDescriptionXml();
            else if (method == "abstract_call") return AbsCall(p);
            else if (method == "stream_verify") return HandleStreamVerify(p);
            else if (method == "fuzz_in_hash") return HandleFuzzInHash(p);
            else {
                return $"{{\"error\":\"Unknown method: {method}\"}}";
            }
    }

    static string AbsStr(string? v) {
        if (v is null) return "\"\"";
        var b = new System.Text.StringBuilder("\"");
        foreach (char c in v) {
            /* The full JSON string grammar, not just quote and backslash. The
               transport is NEWLINE-FRAMED (codegen_pipe reads to the next '\n'),
               so an unescaped control character in an error message would split
               one reply into two lines and hand the second to the NEXT request --
               desynchronising the stream permanently, which is worse than the
               crash the surrounding try/catch replaces. */
            switch (c) {
                case '"':  b.Append("\\\""); break;
                case '\\': b.Append("\\\\"); break;
                case '\b': b.Append("\\b"); break;
                case '\f': b.Append("\\f"); break;
                case '\n': b.Append("\\n"); break;
                case '\r': b.Append("\\r"); break;
                case '\t': b.Append("\\t"); break;
                default:
                    if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4"));
                    else b.Append(c);
                    break;
            }
        }
        b.Append('"');
        return b.ToString();
    }

    static string R(double v) => v.ToString("R", System.Globalization.CultureInfo.InvariantCulture);

    static int DomainCode(OptInputDomain d) => d switch {
        OptInputDomain.RealRange => 0,
        OptInputDomain.RealList => 1,
        OptInputDomain.IntegerRange => 2,
        OptInputDomain.IntegerList => 3,
        _ => throw new InvalidOperationException("unhandled OptInputDomain"),
    };

    static FunctionInfo? AbsLookup(JsonElement p) =>
        FunctionCatalog.Default.TryGet(p.GetProperty("funcName").GetString()!, out var f) ? f : null;

    static string AbsFuncInfo(JsonElement p) {
        var f = AbsLookup(p);
        if (f is null) return "{\"retCode\":2}";
        return $"{{\"name\":{AbsStr(f.Name)},\"group\":{AbsStr(f.Group.ToDisplayName())}"
             + $",\"hint\":{AbsStr(f.Hint)}"
             + $",\"flags\":{(uint)f.Flags},\"nbInput\":{f.Inputs.Length}"
             + $",\"nbOptInput\":{f.OptInputs.Length},\"nbOutput\":{f.Outputs.Length}}}";
    }

    static string AbsInputInfo(JsonElement p) {
        var f = AbsLookup(p);
        int i = GetInt(p, "paramIndex", -1);
        if (f is null || i < 0 || i >= f.Inputs.Length) return "{\"retCode\":2}";
        var ii = f.Inputs[i];
        return $"{{\"type\":{(int)ii.Kind},\"paramName\":{AbsStr(ii.ParamName)},\"flags\":{(uint)ii.Components}}}";
    }

    static string AbsOutputInfo(JsonElement p) {
        var f = AbsLookup(p);
        int i = GetInt(p, "paramIndex", -1);
        if (f is null || i < 0 || i >= f.Outputs.Length) return "{\"retCode\":2}";
        var oo = f.Outputs[i];
        return $"{{\"type\":{(int)oo.Kind},\"paramName\":{AbsStr(oo.ParamName)},\"flags\":{(uint)oo.Flags}}}";
    }

    static string AbsOptInputInfo(JsonElement p) {
        var f = AbsLookup(p);
        int i = GetInt(p, "paramIndex", -1);
        if (f is null || i < 0 || i >= f.OptInputs.Length) return "{\"retCode\":2}";
        var o = f.OptInputs[i];
        var b = new System.Text.StringBuilder($"{{\"type\":{DomainCode(o.Domain)}")
            .Append($",\"paramName\":{AbsStr(o.ParamName)}")
            .Append($",\"flags\":{(uint)o.Flags}")
            .Append($",\"displayName\":{AbsStr(o.DisplayName)}")
            .Append($",\"hint\":{AbsStr(o.Hint)}")
            .Append($",\"defaultValue\":{R(o.DefaultValue)}");
        switch (o.Domain) {
            case OptInputDomain.RealRange r:
                b.Append($",\"min\":{R(r.Min)},\"max\":{R(r.Max)},\"precision\":{r.Precision}")
                 .Append($",\"suggestedStart\":{R(r.SuggestedStart)}")
                 .Append($",\"suggestedEnd\":{R(r.SuggestedEnd)}")
                 .Append($",\"suggestedIncrement\":{R(r.SuggestedIncrement)}");
                break;
            case OptInputDomain.IntegerRange r:
                b.Append($",\"min\":{r.Min},\"max\":{r.Max}")
                 .Append($",\"suggestedStart\":{r.SuggestedStart}")
                 .Append($",\"suggestedEnd\":{r.SuggestedEnd}")
                 .Append($",\"suggestedIncrement\":{r.SuggestedIncrement}");
                break;
            case OptInputDomain.IntegerList l:
                b.Append($",\"valueList\":{AbsStr(l.ToValueListString())}");
                break;
            case OptInputDomain.RealList l:
                b.Append($",\"valueList\":{AbsStr(l.ToValueListString())}");
                break;
            default:
                throw new InvalidOperationException("unhandled OptInputDomain");
        }
        b.Append('}');
        return b.ToString();
    }

    static string AbsForEachFunc() {
        var b = new System.Text.StringBuilder("{\"functions\":[");
        bool first = true;
        foreach (var f in FunctionCatalog.Default) {
            if (!first) b.Append(',');
            first = false;
            b.Append($"{{\"name\":{AbsStr(f.Name)},\"group\":{AbsStr(f.Group.ToDisplayName())}")
             .Append($",\"nbInput\":{f.Inputs.Length},\"nbOptInput\":{f.OptInputs.Length}")
             .Append($",\"nbOutput\":{f.Outputs.Length}}}");
        }
        b.Append("]}");
        return b.ToString();
    }

    /* Measured at RUN TIME from the SHIPPED FunctionDescription. Baking the two
       numbers at generation time made this leg unfailable: it compared C's real
       bytes against constants derived from the same string C's own table is
       built from (#164). Now both sides are real bytes. */
    static string AbsDescriptionXml()
    {
        string xml = TALib.Metadata.FunctionDescription.Xml;
        ulong checksum = 0;
        foreach (char c in xml) checksum += (ulong)(c & 0xFF);
        return $"{{\"length\":{xml.Length},\"checksum\":{checksum}}}";
    }

    /* The JSON key the driver sends a required input under. Price bundles are
       sent one component per set bit; a lone real input keeps its own name,
       and several become inReal0/inReal1/... by rank (test_abstract.c's
       abstract_verify_server_call and expand_input_names agree on this). */
    static string AbsRealInputKey(FunctionInfo f, int slot) {
        int totalReal = 0, rank = 0;
        for (int i = 0; i < f.Inputs.Length; i++) {
            if (f.Inputs[i].Kind != InputKind.Real) continue;
            if (i < slot) rank++;
            totalReal++;
        }
        return totalReal == 1 ? f.Inputs[slot].ParamName : $"inReal{rank}";
    }

    static string AbsComponentKey(PriceComponents c) => c switch {
        PriceComponents.Open => "inOpen",
        PriceComponents.High => "inHigh",
        PriceComponents.Low => "inLow",
        PriceComponents.Close => "inClose",
        PriceComponents.Volume => "inVolume",
        PriceComponents.OpenInterest => "inOpenInterest",
        _ => throw new ArgumentException($"not a single component: {c}"),
    };

    /* abstract_call — the fully generic path, bound through FunctionCall. This
       is a genuinely independent second implementation rather than a reroute to
       the per-function handler (which is what the Rust and Java servers do), so
       a wrong slot index or a transposed price component shows up as diverging
       VALUES against the C reference. */
    static string AbsCall(JsonElement p) {
        var f = AbsLookup(p);
        if (f is null) return "{\"error\":\"Unknown function\"}";
        int startIdx = GetInt(p, "startIdx", 0);
        int endIdx = GetInt(p, "endIdx", 0);
        // Answer the range codes BEFORE sizing anything by the range (#180).
        // `n` below drives every output allocation, so validating after it
        // would turn an out-of-range request into an 800MB-per-output
        // allocation and take the server down instead of returning a code.
        if (startIdx < 0 || startIdx > Core.MAX_INDEX)
            return "{\"binder\":1,\"lookback\":-1,\"retCode\":12,\"outBegIdx\":0,\"outNBElement\":0}";
        if (endIdx < 0 || endIdx > Core.MAX_INDEX || endIdx < startIdx)
            return "{\"binder\":1,\"lookback\":-1,\"retCode\":13,\"outBegIdx\":0,\"outNBElement\":0}";
        int n = endIdx - startIdx + 1;
        if (n < 1) n = 1;

        var call = f.CreateCall(core);
        for (int i = 0; i < f.Inputs.Length; i++) {
            var info = f.Inputs[i];
            if (info.Kind == InputKind.Price) {
                foreach (var comp in info.SignatureOrder) {
                    call.SetPriceInput(i, comp, GetDoubleArray(p, AbsComponentKey(comp)));
                }
            } else if (info.Kind == InputKind.Real) {
                call.SetInput(i, GetDoubleArray(p, AbsRealInputKey(f, i)));
            } else {
                var raw = GetDoubleArray(p, info.ParamName);
                var ints = new int[raw.Length];
                for (int k = 0; k < raw.Length; k++) ints[k] = (int)raw[k];
                call.SetInput(i, ints);
            }
        }

        if (f.UnstableId is FuncUnstId unstId) {
            core.unstablePeriod[(int)unstId] = GetInt(p, "unstablePeriod", 0);
        }

        for (int i = 0; i < f.OptInputs.Length; i++) {
            var o = f.OptInputs[i];
            if (o.Domain is OptInputDomain.RealRange or OptInputDomain.RealList) {
                call.SetOption(i, GetDouble(p, o.ParamName, o.DefaultValue));
            } else {
                call.SetOption(i, GetInt(p, o.ParamName, (int)o.DefaultValue));
            }
        }

        var realOuts = new double[f.Outputs.Length][];
        var intOuts = new int[f.Outputs.Length][];
        for (int k = 0; k < f.Outputs.Length; k++) {
            if (f.Outputs[k].Kind == OutputKind.Real) {
                realOuts[k] = new double[n];
                call.SetOutput(k, realOuts[k]);
            } else {
                intOuts[k] = new int[n];
                call.SetOutput(k, intOuts[k]);
            }
        }

        int lookback = call.Lookback();
        RetCode rc = call.TryInvoke(startIdx, endIdx, out OutRange range);

        var b = new System.Text.StringBuilder();
        b.Append($"{{\"lookback\":{lookback},\"retCode\":{(int)rc}")
         .Append($",\"outBegIdx\":{range.BegIdx},\"outNBElement\":{range.Count}");
        int realRank = 0, intRank = 0;
        for (int k = 0; k < f.Outputs.Length; k++) {
            if (f.Outputs[k].Kind == OutputKind.Real) {
                string key = realRank == 0 ? "outReal" : $"outReal{realRank}";
                realRank++;
                b.Append($",\"{key}\":").Append(FormatArray(realOuts[k], range.Count));
            } else {
                string key = intRank == 0 ? "outInteger" : $"outInteger{intRank}";
                intRank++;
                b.Append($",\"{key}\":").Append(FormatIntArray(intOuts[k], range.Count));
            }
        }
        b.Append('}');
        return b.ToString();
    }

    // ---- stream_verify: C# stream vs C# batch, bitwise ----

    /* Strict comparator for SAME-TIER legs: peek vs update, Value vs update,
       clone vs clone, and the int.MinValue sentinel pair all run ONE code path
       twice, so they have no licence to differ in a single bit. -0.0 != +0.0
       here and NaN == NaN -- which is exactly why a <NAME>_Value's own `==`
       must never be used for these: record-struct equality says the opposite
       of both, so it would pass on precisely what these legs look for. */
    static bool SvBne(double a, double b) =>
        BitConverter.DoubleToInt64Bits(a) != BitConverter.DoubleToInt64Bits(b);

    /* Cross-tier comparator: stream vs batch, fill vs batch. Bits that differ
       but compare equal are +0.0 vs -0.0 (issue #147) -- counted as benign,
       never a mismatch, because the two tiers reach a zero by different but
       equally correct routes.
       `zsign` is a `ref` to a REQUEST-SCOPED local, never a static: one process
       answers many requests and a static would carry one function's count into
       the next. (Java passes a one-element array here only because Java has no
       `ref`.) */
    static bool SvXtierNe(double a, double b, ref long zsign) {
        if (!SvBne(a, b)) return false;
        if (a == b) { zsign++; return false; }
        return true;
    }

    /* The allocation probe accumulates one output component into a local and
       consumes it here, AFTER the measured region. Without a consumer the JIT
       can prove the Update results dead and delete the calls, and the probe
       then reads 0 bytes for a loop that never ran. Never read. */
    static double svUpdSink;

    /* Candle-settings rounds (mirror the C/Rust/Java sweep): defaults /
       avgPeriod+3 / avgPeriod=0 (instant candle) / rangeType=Shadows.
       Goes through the SHIPPED CoreBuilder, so the validation exercised is the
       library's own and not a second copy living in the server; Build() takes a
       snapshot, so a built Core never aliases the builder.
       Each round is derived from Core.DefaultCandleSettings, never from the
       previous round -- a fresh builder is seeded with exactly those defaults,
       so the rounds cannot compound. (C# needs none of Java's care about
       editing the shared defaults in place: Core clones the array and
       CandleSetting is immutable, so replacing a slot reaches nothing else.)
       WHAT THESE FOUR ROUNDS DO NOT TEST: the open-time snapshot. Each round
       builds its Core and opens on it, so the step's snapshot and the Core's
       live settings hold the same value and a step reading the wrong one is
       invisible here. SvMutateLiveCandles below is what tests that. */
    static CoreBuilder SvApplyCandleRound(CoreBuilder b, int rd) {
        if (rd == 0) return b;
        for (int ci = 0; ci < Core.DefaultCandleSettings.Length; ci++) {
            CandleSetting cs = Core.DefaultCandleSettings[ci];
            if (rd == 1)
                b = b.CandleSetting((CandleSettingType)ci, cs.RangeType, cs.AvgPeriod + 3, cs.Factor);
            else if (rd == 2)
                b = b.CandleSetting((CandleSettingType)ci, cs.RangeType, 0, cs.Factor);
            else if (rd == 3)
                b = b.CandleSetting((CandleSettingType)ci, TALib.RangeType.Shadows, cs.AvgPeriod, cs.Factor);
        }
        return b;
    }

    /* Overwrite a BUILT Core's live candle settings, in place.
       `Core.candleSettings` is `internal readonly CandleSetting[]` -- the
       REFERENCE is readonly, the ELEMENTS are not -- and CandleSetting's
       constructor is internal. Both are reachable because the server csproj
       compiles the library sources into its own assembly.
       This is the one thing CoreBuilder deliberately cannot express: a
       settings change AFTER the Core exists, which is precisely what the
       streaming open-time snapshot contract is about.
       All three fields move, and to values no round uses, so a step reading
       live settings must produce a DIFFERENT number rather than a
       differently-spelled same one.
       The caller saves and restores: every later leg in the round runs against
       the round's settings, not these. */
    static void SvMutateLiveCandles(Core c) {
        for (int ci = 0; ci < c.candleSettings.Length; ci++) {
            CandleSetting cs = c.candleSettings[ci];
            c.candleSettings[ci] = new CandleSetting(
                cs.RangeType == TALib.RangeType.Shadows ? TALib.RangeType.HighLow
                                                       : TALib.RangeType.Shadows,
                (cs.AvgPeriod + 7) % 13,
                cs.Factor * 2.0 + 0.5);
        }
    }

    static void SvRestoreLiveCandles(Core c, CandleSetting[] saved) {
        Array.Copy(saved, c.candleSettings, saved.Length);
    }

    static string Sv_AC(JsonElement req) {
        int svShape = GetInt(req, "gen_shape", 0);
        int svSeed = GetInt(req, "gen_seed", 0);
        int svN = GetInt(req, "gen_n", 0);
        if (svN < 2) svN = 2;
        if (svN > 256) svN = 256;
        int svK = GetInt(req, "unstablePeriod", 0);
        int svCompat = GetInt(req, "compatibility", 0);
        if (svCompat != 0) {
            return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
        }
        int optInFastPeriod = GetInt(req, "optInFastPeriod", 5);
        int optInSlowPeriod = GetInt(req, "optInSlowPeriod", 34);
        int optInSignalPeriod = GetInt(req, "optInSignalPeriod", 5);
        double[] fz_o = new double[svN];
        double[] fz_h = new double[svN];
        double[] fz_l = new double[svN];
        double[] fz_c = new double[svN];
        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        double[] b0 = new double[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.AC_Impl(0, svN - 1, fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.AC_Lookback(optInFastPeriod, optInSlowPeriod, optInSignalPeriod);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.AC_Open(fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                Core.AC_Stream _fh = c2.AC_OpenAndFill(fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                try { _ = c2.AC_OpenAndFill(fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, fz_h); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inHigh */ }
                try { _ = c2.AC_OpenAndFill(fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, fz_l); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inLow */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.AC_OpenAndFill(fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, fz_h.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.AC_Stream st;
                try { st = c2.AC_Open(fz_h[..p], fz_l[..p], optInFastPeriod, optInSlowPeriod, optInSignalPeriod); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                double v0 = st.Value;
                if (SvXtierNe(v0, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        double pk = st.Peek(fz_h[t], fz_l[t]);
                        double up = st.Update(fz_h[t], fz_l[t]);
                        if (SvBne(pk, up)) peekAll = false;
                        _ = st.Peek(fz_h[t - 1], fz_l[t - 1]);
                        double vc = st.Value;
                        if (SvBne(vc, up)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    } else {
                        double up = st.Update(fz_h[t], fz_l[t]);
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.AC_Stream stu = c2.AC_Open(fz_h[..p], fz_l[..p], optInFastPeriod, optInSlowPeriod, optInSignalPeriod);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_h.AsSpan(p, 0), fz_l.AsSpan(p, 0), u0);
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), new double[0]); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_h.AsSpan(p)); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), u0);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.AC_Stream sA = c2.AC_Open(fz_h[..p0], fz_l[..p0], optInFastPeriod, optInSlowPeriod, optInSignalPeriod);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_h[t], fz_l[t]);
                        Core.AC_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            double uA = sA.Update(fz_h[t], fz_l[t]);
                            double uB = sB.Update(fz_h[t], fz_l[t]);
                            if (SvBne(uA, uB) || SvXtierNe(uA, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.AC_Stream sQ = c2.AC_Open(fz_h[..pa], fz_l[..pa], optInFastPeriod, optInSlowPeriod, optInSignalPeriod);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            double uq = sQ.Update(fz_h[t], fz_l[t]);
                            sink += uq;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.AC_Open(fz_h[..lb], fz_l[..lb], optInFastPeriod, optInSlowPeriod, optInSignalPeriod); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.AC_Stream sD = c2.AC_Open(fz_h, fz_l, int.MinValue, int.MinValue, int.MinValue);
                Core.AC_Stream sE = c2.AC_Open(fz_h, fz_l, 5, 34, 5);
                double vD = sD.Value;
                double vE = sE.Value;
                if (SvBne(vD, vE)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
                int Sidx = lb + (svN - lb) / 3;
                if (Sidx > lb && Sidx < svN - 1) {
                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.AC_Impl(Sidx, svN - 1, fz_h, fz_l, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
                    if (rcS == RetCode.Success && nbS > 0) {
                        try {
                            Core.AC_Stream stA = c2.AC_OpenInternal(fz_h[..svN], fz_l[..svN], Sidx, optInFastPeriod, optInSlowPeriod, optInSignalPeriod);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
                            if (stA.OutRange.BegIdx != begS || stA.OutRange.Count != nbS) rangeOk = false;
                        } catch (ArgumentException) { rangeOk = false; if (diag.Length == 0) diag = ",\"anchoredOpenRejected\":1"; }
                    }
                }
            }
        }
        string extra = ",\"updAlloc\":" + updAlloc;
        return "{\"retCode\":0,\"beg\":" + beg + ",\"nb\":" + nb + ",\"legs\":" + legs + ",\"fill_checked\":" + fillChecked + ",\"fill_ok\":" + (fillOk ? 1 : 0) + ",\"ufill_checked\":" + ufillChecked + ",\"ufill_ok\":" + (ufillOk ? 1 : 0) + ",\"range_checked\":" + rangeChecked + ",\"range_legs\":" + rangeLegs + ",\"range_sites\":" + rangeSites + ",\"range_sites_n\":4,\"range_ok\":" + (rangeOk ? 1 : 0) + ",\"ok\":" + ((allOk && fillOk && ufillOk && rangeOk) ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + extra + diag + "}";
    }

    static string Sv_ACCBANDS(JsonElement req) {
        int svShape = GetInt(req, "gen_shape", 0);
        int svSeed = GetInt(req, "gen_seed", 0);
        int svN = GetInt(req, "gen_n", 0);
        if (svN < 2) svN = 2;
        if (svN > 256) svN = 256;
        int svK = GetInt(req, "unstablePeriod", 0);
        int svCompat = GetInt(req, "compatibility", 0);
        if (svCompat != 0) {
            return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
        }
        int optInTimePeriod = GetInt(req, "optInTimePeriod", 20);
        double[] fz_o = new double[svN];
        double[] fz_h = new double[svN];
        double[] fz_l = new double[svN];
        double[] fz_c = new double[svN];
        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        double[] b0 = new double[svN];
        double[] b1 = new double[svN];
        double[] b2 = new double[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.ACCBANDS_Impl(0, svN - 1, fz_h, fz_l, fz_c, optInTimePeriod, out beg, out nb, b0, b1, b2); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.ACCBANDS_Lookback(optInTimePeriod);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.ACCBANDS_Open(fz_h, fz_l, fz_c, optInTimePeriod); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                double[] f1 = new double[svN];
                Array.Fill(f1, (double)-1.2345678901234e300);
                double[] f2 = new double[svN];
                Array.Fill(f2, (double)-1.2345678901234e300);
                Core.ACCBANDS_Stream _fh = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, f2);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f1[bi], b1[bi], ref zsign)) fillOk = false;
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f2[bi], b2[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f1[bi] != (double)-1.2345678901234e300) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f2[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_h, f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inHigh */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_l, f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inLow */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_c, f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inClose */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, fz_h, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inHigh */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, fz_l, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inLow */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, fz_c, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inClose */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, fz_h); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inHigh */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, fz_l); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inLow */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inClose */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f0, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases output 0 */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, f0); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases output 0 */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, f1); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases output 1 */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0.AsSpan(0, svN - 1), f0.AsSpan(1, svN - 1), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/1 partially overlap (offset) */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0.AsSpan(0, svN - 1), f0.AsSpan(0, svN), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/1 partially overlap (same start, longer) */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0.AsSpan(0, svN - 1), f1, f0.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/2 partially overlap (offset) */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0.AsSpan(0, svN - 1), f1, f0.AsSpan(0, svN)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/2 partially overlap (same start, longer) */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1.AsSpan(0, svN - 1), f1.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 1/2 partially overlap (offset) */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1.AsSpan(0, svN - 1), f1.AsSpan(0, svN)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 1/2 partially overlap (same start, longer) */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_h.AsSpan(1, svN - 1), f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, fz_h.AsSpan(1, svN - 1), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 partially overlaps an input */ }
                try { _ = c2.ACCBANDS_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0, f1, fz_h.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.ACCBANDS_Stream st;
                try { st = c2.ACCBANDS_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInTimePeriod); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                Core.ACCBANDS_Value v0 = st.Value;
                if (SvXtierNe(v0.RealUpperBand, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                if (SvXtierNe(v0.RealMiddleBand, b1[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":1,\"where\":\"open\""; }
                if (SvXtierNe(v0.RealLowerBand, b2[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":2,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        Core.ACCBANDS_Value pk = st.Peek(fz_h[t], fz_l[t], fz_c[t]);
                        Core.ACCBANDS_Value up = st.Update(fz_h[t], fz_l[t], fz_c[t]);
                        if (SvBne(pk.RealUpperBand, up.RealUpperBand)) peekAll = false;
                        if (SvBne(pk.RealMiddleBand, up.RealMiddleBand)) peekAll = false;
                        if (SvBne(pk.RealLowerBand, up.RealLowerBand)) peekAll = false;
                        _ = st.Peek(fz_h[t - 1], fz_l[t - 1], fz_c[t - 1]);
                        Core.ACCBANDS_Value vc = st.Value;
                        if (SvBne(vc.RealUpperBand, up.RealUpperBand)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvBne(vc.RealMiddleBand, up.RealMiddleBand)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvBne(vc.RealLowerBand, up.RealLowerBand)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up.RealUpperBand, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealUpperBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealMiddleBand, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":1,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b1[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealMiddleBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealLowerBand, b2[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":2,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b2[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealLowerBand).ToString("x16") + "\""; }
                    } else {
                        Core.ACCBANDS_Value up = st.Update(fz_h[t], fz_l[t], fz_c[t]);
                        if (SvXtierNe(up.RealUpperBand, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealUpperBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealMiddleBand, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":1,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b1[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealMiddleBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealLowerBand, b2[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":2,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b2[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealLowerBand).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.ACCBANDS_Stream stu = c2.ACCBANDS_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInTimePeriod);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        double[] u1 = new double[svN];
                        Array.Fill(u1, (double)-1.2345678901234e300);
                        double[] u2 = new double[svN];
                        Array.Fill(u2, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_h.AsSpan(p, 0), fz_l.AsSpan(p, 0), fz_c.AsSpan(p, 0), u0, u1, u2);
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), new double[0], u1, u2); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), fz_h.AsSpan(p), u1, u2); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), u0, u1, u2);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = p; t < svN; t++) if (SvXtierNe(u1[t - p], b1[t - beg], ref zsign)) ufillOk = false;
                        for (int t = p; t < svN; t++) if (SvXtierNe(u2[t - p], b2[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u1[t] != (double)-1.2345678901234e300) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u2[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.ACCBANDS_Stream sA = c2.ACCBANDS_Open(fz_h[..p0], fz_l[..p0], fz_c[..p0], optInTimePeriod);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                        Core.ACCBANDS_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            Core.ACCBANDS_Value uA = sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                            Core.ACCBANDS_Value uB = sB.Update(fz_h[t], fz_l[t], fz_c[t]);
                            if (SvBne(uA.RealUpperBand, uB.RealUpperBand) || SvXtierNe(uA.RealUpperBand, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                            if (SvBne(uA.RealMiddleBand, uB.RealMiddleBand) || SvXtierNe(uA.RealMiddleBand, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                            if (SvBne(uA.RealLowerBand, uB.RealLowerBand) || SvXtierNe(uA.RealLowerBand, b2[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.ACCBANDS_Stream sQ = c2.ACCBANDS_Open(fz_h[..pa], fz_l[..pa], fz_c[..pa], optInTimePeriod);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            Core.ACCBANDS_Value uq = sQ.Update(fz_h[t], fz_l[t], fz_c[t]);
                            sink += uq.RealUpperBand;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.ACCBANDS_Open(fz_h[..lb], fz_l[..lb], fz_c[..lb], optInTimePeriod); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.ACCBANDS_Stream sD = c2.ACCBANDS_Open(fz_h, fz_l, fz_c, int.MinValue);
                Core.ACCBANDS_Stream sE = c2.ACCBANDS_Open(fz_h, fz_l, fz_c, 20);
                Core.ACCBANDS_Value vD = sD.Value;
                Core.ACCBANDS_Value vE = sE.Value;
                if (SvBne(vD.RealUpperBand, vE.RealUpperBand)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
                if (SvBne(vD.RealMiddleBand, vE.RealMiddleBand)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
                if (SvBne(vD.RealLowerBand, vE.RealLowerBand)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
                int Sidx = lb + (svN - lb) / 3;
                if (Sidx > lb && Sidx < svN - 1) {
                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.ACCBANDS_Impl(Sidx, svN - 1, fz_h, fz_l, fz_c, optInTimePeriod, out begS, out nbS, b0, b1, b2); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
                    if (rcS == RetCode.Success && nbS > 0) {
                        try {
                            Core.ACCBANDS_Stream stA = c2.ACCBANDS_OpenInternal(fz_h[..svN], fz_l[..svN], fz_c[..svN], Sidx, optInTimePeriod);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
                            if (stA.OutRange.BegIdx != begS || stA.OutRange.Count != nbS) rangeOk = false;
                        } catch (ArgumentException) { rangeOk = false; if (diag.Length == 0) diag = ",\"anchoredOpenRejected\":1"; }
                    }
                }
            }
        }
        string extra = ",\"updAlloc\":" + updAlloc;
        return "{\"retCode\":0,\"beg\":" + beg + ",\"nb\":" + nb + ",\"legs\":" + legs + ",\"fill_checked\":" + fillChecked + ",\"fill_ok\":" + (fillOk ? 1 : 0) + ",\"ufill_checked\":" + ufillChecked + ",\"ufill_ok\":" + (ufillOk ? 1 : 0) + ",\"range_checked\":" + rangeChecked + ",\"range_legs\":" + rangeLegs + ",\"range_sites\":" + rangeSites + ",\"range_sites_n\":4,\"range_ok\":" + (rangeOk ? 1 : 0) + ",\"ok\":" + ((allOk && fillOk && ufillOk && rangeOk) ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + extra + diag + "}";
    }

    static string Sv_ACOS(JsonElement req) {
        int svShape = GetInt(req, "gen_shape", 0);
        int svSeed = GetInt(req, "gen_seed", 0);
        int svN = GetInt(req, "gen_n", 0);
        if (svN < 2) svN = 2;
        if (svN > 256) svN = 256;
        int svK = GetInt(req, "unstablePeriod", 0);
        int svCompat = GetInt(req, "compatibility", 0);
        if (svCompat != 0) {
            return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
        }
        double[] fz_o = new double[svN];
        double[] fz_h = new double[svN];
        double[] fz_l = new double[svN];
        double[] fz_c = new double[svN];
        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        double[] b0 = new double[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.ACOS_Impl(0, svN - 1, fz_c, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.ACOS_Lookback();
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.ACOS_Open(fz_c); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                Core.ACOS_Stream _fh = c2.ACOS_OpenAndFill(fz_c, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                try { _ = c2.ACOS_OpenAndFill(fz_c, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inReal */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.ACOS_OpenAndFill(fz_c, fz_c.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.ACOS_Stream st;
                try { st = c2.ACOS_Open(fz_c[..p]); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                double v0 = st.Value;
                if (SvXtierNe(v0, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        double pk = st.Peek(fz_c[t]);
                        double up = st.Update(fz_c[t]);
                        if (SvBne(pk, up)) peekAll = false;
                        _ = st.Peek(fz_c[t - 1]);
                        double vc = st.Value;
                        if (SvBne(vc, up)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    } else {
                        double up = st.Update(fz_c[t]);
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.ACOS_Stream stu = c2.ACOS_Open(fz_c[..p]);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_c.AsSpan(p, 0), u0);
                        try { stu.UpdateAndFill(fz_c.AsSpan(p), new double[0]); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_c.AsSpan(p), fz_c.AsSpan(p)); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_c.AsSpan(p), u0);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
