                    ufillChecked = 1;
                    try {
                        Core.ATR_Stream stu = c2.ATR_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInTimePeriod);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_h.AsSpan(p, 0), fz_l.AsSpan(p, 0), fz_c.AsSpan(p, 0), u0);
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), new double[0]); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), fz_h.AsSpan(p)); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), u0);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.ATR_Stream sA = c2.ATR_Open(fz_h[..p0], fz_l[..p0], fz_c[..p0], optInTimePeriod);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                        Core.ATR_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            double uA = sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                            double uB = sB.Update(fz_h[t], fz_l[t], fz_c[t]);
                            if (SvBne(uA, uB) || SvXtierNe(uA, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.ATR_Stream sQ = c2.ATR_Open(fz_h[..pa], fz_l[..pa], fz_c[..pa], optInTimePeriod);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            double uq = sQ.Update(fz_h[t], fz_l[t], fz_c[t]);
                            sink += uq;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.ATR_Open(fz_h[..lb], fz_l[..lb], fz_c[..lb], optInTimePeriod); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.ATR_Stream sD = c2.ATR_Open(fz_h, fz_l, fz_c, int.MinValue);
                Core.ATR_Stream sE = c2.ATR_Open(fz_h, fz_l, fz_c, 14);
