            catch (ArgumentException) { eFill = true; }
            bool eOk = eOpen && eFill;
            return "{\"retCode\":2,\"legs\":0,\"nb\":0,\"openRejects\":" + (eOk ? 1 : 0) + ",\"enumRejects\":" + ((eOpen ? 1 : 0) + (eFill ? 1 : 0)) + ",\"ok\":" + (eOk ? 1 : 0) + ",\"peek_ok\":1}";
        }
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            cb = cb.UnstablePeriod((FuncUnstId)23, svK);
            cb = cb.UnstablePeriod((FuncUnstId)14, svK);
            cb = cb.UnstablePeriod((FuncUnstId)13, svK);
            cb = cb.UnstablePeriod((FuncUnstId)5, svK);
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.BBANDS_Impl(0, svN - 1, fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, out beg, out nb, b0, b1, b2); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.BBANDS_Lookback(optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.BBANDS_Open(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                double[] f1 = new double[svN];
                Array.Fill(f1, (double)-1.2345678901234e300);
                double[] f2 = new double[svN];
                Array.Fill(f2, (double)-1.2345678901234e300);
                Core.BBANDS_Stream _fh = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1, f2);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f1[bi], b1[bi], ref zsign)) fillOk = false;
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f2[bi], b2[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f1[bi] != (double)-1.2345678901234e300) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f2[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, fz_c, f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inReal */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, fz_c, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inReal */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inReal */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f0, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases output 0 */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1, f0); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases output 0 */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1, f1); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases output 1 */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0.AsSpan(0, svN - 1), f0.AsSpan(1, svN - 1), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/1 partially overlap (offset) */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0.AsSpan(0, svN - 1), f0.AsSpan(0, svN), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/1 partially overlap (same start, longer) */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0.AsSpan(0, svN - 1), f1, f0.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/2 partially overlap (offset) */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0.AsSpan(0, svN - 1), f1, f0.AsSpan(0, svN)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/2 partially overlap (same start, longer) */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1.AsSpan(0, svN - 1), f1.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 1/2 partially overlap (offset) */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1.AsSpan(0, svN - 1), f1.AsSpan(0, svN)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 1/2 partially overlap (same start, longer) */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, fz_c.AsSpan(1, svN - 1), f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, fz_c.AsSpan(1, svN - 1), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 partially overlaps an input */ }
                try { _ = c2.BBANDS_OpenAndFill(fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, f0, f1, fz_c.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.BBANDS_Stream st;
                try { st = c2.BBANDS_Open(fz_c[..p], optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                Core.BBANDS_Value v0 = st.Value;
                if (SvXtierNe(v0.RealUpperBand, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                if (SvXtierNe(v0.RealMiddleBand, b1[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":1,\"where\":\"open\""; }
                if (SvXtierNe(v0.RealLowerBand, b2[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":2,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        Core.BBANDS_Value pk = st.Peek(fz_c[t]);
                        Core.BBANDS_Value up = st.Update(fz_c[t]);
                        if (SvBne(pk.RealUpperBand, up.RealUpperBand)) peekAll = false;
                        if (SvBne(pk.RealMiddleBand, up.RealMiddleBand)) peekAll = false;
                        if (SvBne(pk.RealLowerBand, up.RealLowerBand)) peekAll = false;
                        _ = st.Peek(fz_c[t - 1]);
                        Core.BBANDS_Value vc = st.Value;
                        if (SvBne(vc.RealUpperBand, up.RealUpperBand)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvBne(vc.RealMiddleBand, up.RealMiddleBand)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvBne(vc.RealLowerBand, up.RealLowerBand)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up.RealUpperBand, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealUpperBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealMiddleBand, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":1,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b1[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealMiddleBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealLowerBand, b2[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":2,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b2[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealLowerBand).ToString("x16") + "\""; }
                    } else {
                        Core.BBANDS_Value up = st.Update(fz_c[t]);
                        if (SvXtierNe(up.RealUpperBand, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealUpperBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealMiddleBand, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":1,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b1[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealMiddleBand).ToString("x16") + "\""; }
                        if (SvXtierNe(up.RealLowerBand, b2[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":2,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b2[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.RealLowerBand).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.BBANDS_Stream stu = c2.BBANDS_Open(fz_c[..p], optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        double[] u1 = new double[svN];
                        Array.Fill(u1, (double)-1.2345678901234e300);
                        double[] u2 = new double[svN];
                        Array.Fill(u2, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_c.AsSpan(p, 0), u0, u1, u2);
                        try { stu.UpdateAndFill(fz_c.AsSpan(p), new double[0], u1, u2); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_c.AsSpan(p), fz_c.AsSpan(p), u1, u2); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_c.AsSpan(p), u0, u1, u2);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = p; t < svN; t++) if (SvXtierNe(u1[t - p], b1[t - beg], ref zsign)) ufillOk = false;
                        for (int t = p; t < svN; t++) if (SvXtierNe(u2[t - p], b2[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u1[t] != (double)-1.2345678901234e300) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u2[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.BBANDS_Stream sA = c2.BBANDS_Open(fz_c[..p0], optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_c[t]);
                        Core.BBANDS_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            Core.BBANDS_Value uA = sA.Update(fz_c[t]);
                            Core.BBANDS_Value uB = sB.Update(fz_c[t]);
                            if (SvBne(uA.RealUpperBand, uB.RealUpperBand) || SvXtierNe(uA.RealUpperBand, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                            if (SvBne(uA.RealMiddleBand, uB.RealMiddleBand) || SvXtierNe(uA.RealMiddleBand, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                            if (SvBne(uA.RealLowerBand, uB.RealLowerBand) || SvXtierNe(uA.RealLowerBand, b2[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.BBANDS_Stream sQ = c2.BBANDS_Open(fz_c[..pa], optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            Core.BBANDS_Value uq = sQ.Update(fz_c[t]);
                            sink += uq.RealUpperBand;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.BBANDS_Open(fz_c[..lb], optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.BBANDS_Stream sD = c2.BBANDS_Open(fz_c, int.MinValue, optInNbDevUp, optInNbDevDn, optInMAType);
                Core.BBANDS_Stream sE = c2.BBANDS_Open(fz_c, 20, optInNbDevUp, optInNbDevDn, optInMAType);
                Core.BBANDS_Value vD = sD.Value;
                Core.BBANDS_Value vE = sE.Value;
                if (SvBne(vD.RealUpperBand, vE.RealUpperBand)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
                if (SvBne(vD.RealMiddleBand, vE.RealMiddleBand)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
                if (SvBne(vD.RealLowerBand, vE.RealLowerBand)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
                int Sidx = lb + (svN - lb) / 3;
                if (Sidx > lb && Sidx < svN - 1) {
                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.BBANDS_Impl(Sidx, svN - 1, fz_c, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType, out begS, out nbS, b0, b1, b2); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
                    if (rcS == RetCode.Success && nbS > 0) {
                        try {
                            Core.BBANDS_Stream stA = c2.BBANDS_OpenInternal(fz_c[..svN], Sidx, optInTimePeriod, optInNbDevUp, optInNbDevDn, optInMAType);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
                            if (stA.OutRange.BegIdx != begS || stA.OutRange.Count != nbS) rangeOk = false;
                        } catch (ArgumentException) { rangeOk = false; if (diag.Length == 0) diag = ",\"anchoredOpenRejected\":1"; }
                    }
                }
            }
        }
        string extra = ",\"updAlloc\":" + updAlloc;
        return "{\"retCode\":0,\"beg\":" + beg + ",\"nb\":" + nb + ",\"legs\":" + legs + ",\"fill_checked\":" + fillChecked + ",\"fill_ok\":" + (fillOk ? 1 : 0) + ",\"ufill_checked\":" + ufillChecked + ",\"ufill_ok\":" + (ufillOk ? 1 : 0) + ",\"range_checked\":" + rangeChecked + ",\"range_legs\":" + rangeLegs + ",\"range_sites\":" + rangeSites + ",\"range_sites_n\":4,\"range_ok\":" + (rangeOk ? 1 : 0) + ",\"ok\":" + ((allOk && fillOk && ufillOk && rangeOk) ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + extra + diag + "}";
    }

    static string Sv_BETA(JsonElement req) {
        int svShape = GetInt(req, "gen_shape", 0);
        int svSeed = GetInt(req, "gen_seed", 0);
        int svN = GetInt(req, "gen_n", 0);
        if (svN < 2) svN = 2;
        if (svN > 256) svN = 256;
        int svK = GetInt(req, "unstablePeriod", 0);
        int svCompat = GetInt(req, "compatibility", 0);
        if (svCompat != 0) {
            return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
        }
        int optInTimePeriod = GetInt(req, "optInTimePeriod", 5);
        double[] fz_o = new double[svN];
        double[] fz_h = new double[svN];
        double[] fz_l = new double[svN];
        double[] fz_c = new double[svN];
        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        double[] b0 = new double[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.BETA_Impl(0, svN - 1, fz_c, fz_v, optInTimePeriod, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.BETA_Lookback(optInTimePeriod);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.BETA_Open(fz_c, fz_v, optInTimePeriod); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                Core.BETA_Stream _fh = c2.BETA_OpenAndFill(fz_c, fz_v, optInTimePeriod, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                try { _ = c2.BETA_OpenAndFill(fz_c, fz_v, optInTimePeriod, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inReal0 */ }
                try { _ = c2.BETA_OpenAndFill(fz_c, fz_v, optInTimePeriod, fz_v); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inReal1 */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.BETA_OpenAndFill(fz_c, fz_v, optInTimePeriod, fz_c.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.BETA_Stream st;
                try { st = c2.BETA_Open(fz_c[..p], fz_v[..p], optInTimePeriod); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                double v0 = st.Value;
                if (SvXtierNe(v0, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        double pk = st.Peek(fz_c[t], fz_v[t]);
                        double up = st.Update(fz_c[t], fz_v[t]);
                        if (SvBne(pk, up)) peekAll = false;
                        _ = st.Peek(fz_c[t - 1], fz_v[t - 1]);
                        double vc = st.Value;
                        if (SvBne(vc, up)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    } else {
                        double up = st.Update(fz_c[t], fz_v[t]);
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.BETA_Stream stu = c2.BETA_Open(fz_c[..p], fz_v[..p], optInTimePeriod);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_c.AsSpan(p, 0), fz_v.AsSpan(p, 0), u0);
                        try { stu.UpdateAndFill(fz_c.AsSpan(p), fz_v.AsSpan(p), new double[0]); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_c.AsSpan(p), fz_v.AsSpan(p), fz_c.AsSpan(p)); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_c.AsSpan(p), fz_v.AsSpan(p), u0);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.BETA_Stream sA = c2.BETA_Open(fz_c[..p0], fz_v[..p0], optInTimePeriod);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_c[t], fz_v[t]);
                        Core.BETA_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            double uA = sA.Update(fz_c[t], fz_v[t]);
                            double uB = sB.Update(fz_c[t], fz_v[t]);
                            if (SvBne(uA, uB) || SvXtierNe(uA, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.BETA_Stream sQ = c2.BETA_Open(fz_c[..pa], fz_v[..pa], optInTimePeriod);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            double uq = sQ.Update(fz_c[t], fz_v[t]);
                            sink += uq;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.BETA_Open(fz_c[..lb], fz_v[..lb], optInTimePeriod); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.BETA_Stream sD = c2.BETA_Open(fz_c, fz_v, int.MinValue);
                Core.BETA_Stream sE = c2.BETA_Open(fz_c, fz_v, 5);
                double vD = sD.Value;
                double vE = sE.Value;
                if (SvBne(vD, vE)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
                int Sidx = lb + (svN - lb) / 3;
                if (Sidx > lb && Sidx < svN - 1) {
                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.BETA_Impl(Sidx, svN - 1, fz_c, fz_v, optInTimePeriod, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
                    if (rcS == RetCode.Success && nbS > 0) {
                        try {
                            Core.BETA_Stream stA = c2.BETA_OpenInternal(fz_c[..svN], fz_v[..svN], Sidx, optInTimePeriod);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
                            if (stA.OutRange.BegIdx != begS || stA.OutRange.Count != nbS) rangeOk = false;
                        } catch (ArgumentException) { rangeOk = false; if (diag.Length == 0) diag = ",\"anchoredOpenRejected\":1"; }
                    }
                }
            }
        }
        string extra = ",\"updAlloc\":" + updAlloc;
        return "{\"retCode\":0,\"beg\":" + beg + ",\"nb\":" + nb + ",\"legs\":" + legs + ",\"fill_checked\":" + fillChecked + ",\"fill_ok\":" + (fillOk ? 1 : 0) + ",\"ufill_checked\":" + ufillChecked + ",\"ufill_ok\":" + (ufillOk ? 1 : 0) + ",\"range_checked\":" + rangeChecked + ",\"range_legs\":" + rangeLegs + ",\"range_sites\":" + rangeSites + ",\"range_sites_n\":4,\"range_ok\":" + (rangeOk ? 1 : 0) + ",\"ok\":" + ((allOk && fillOk && ufillOk && rangeOk) ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + extra + diag + "}";
    }

    static string Sv_BOP(JsonElement req) {
