        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.CCI_Impl(0, svN - 1, fz_h, fz_l, fz_c, optInTimePeriod, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.CCI_Lookback(optInTimePeriod);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.CCI_Open(fz_h, fz_l, fz_c, optInTimePeriod); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                Core.CCI_Stream _fh = c2.CCI_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                try { _ = c2.CCI_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_h); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inHigh */ }
                try { _ = c2.CCI_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_l); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inLow */ }
                try { _ = c2.CCI_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inClose */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.CCI_OpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod, fz_h.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.CCI_Stream st;
                try { st = c2.CCI_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInTimePeriod); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                double v0 = st.Value;
                if (SvXtierNe(v0, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        double pk = st.Peek(fz_h[t], fz_l[t], fz_c[t]);
                        double up = st.Update(fz_h[t], fz_l[t], fz_c[t]);
                        if (SvBne(pk, up)) peekAll = false;
                        _ = st.Peek(fz_h[t - 1], fz_l[t - 1], fz_c[t - 1]);
                        double vc = st.Value;
                        if (SvBne(vc, up)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    } else {
                        double up = st.Update(fz_h[t], fz_l[t], fz_c[t]);
                        if (SvXtierNe(up, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.CCI_Stream stu = c2.CCI_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInTimePeriod);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_h.AsSpan(p, 0), fz_l.AsSpan(p, 0), fz_c.AsSpan(p, 0), u0);
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), new double[0]); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), fz_h.AsSpan(p)); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), u0);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.CCI_Stream sA = c2.CCI_Open(fz_h[..p0], fz_l[..p0], fz_c[..p0], optInTimePeriod);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                        Core.CCI_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            double uA = sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                            double uB = sB.Update(fz_h[t], fz_l[t], fz_c[t]);
                            if (SvBne(uA, uB) || SvXtierNe(uA, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.CCI_Stream sQ = c2.CCI_Open(fz_h[..pa], fz_l[..pa], fz_c[..pa], optInTimePeriod);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            double uq = sQ.Update(fz_h[t], fz_l[t], fz_c[t]);
                            sink += uq;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.CCI_Open(fz_h[..lb], fz_l[..lb], fz_c[..lb], optInTimePeriod); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.CCI_Stream sD = c2.CCI_Open(fz_h, fz_l, fz_c, int.MinValue);
                Core.CCI_Stream sE = c2.CCI_Open(fz_h, fz_l, fz_c, 14);
                double vD = sD.Value;
                double vE = sE.Value;
                if (SvBne(vD, vE)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
                int Sidx = lb + (svN - lb) / 3;
                if (Sidx > lb && Sidx < svN - 1) {
                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.CCI_Impl(Sidx, svN - 1, fz_h, fz_l, fz_c, optInTimePeriod, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
                    if (rcS == RetCode.Success && nbS > 0) {
                        try {
                            Core.CCI_Stream stA = c2.CCI_OpenInternal(fz_h[..svN], fz_l[..svN], fz_c[..svN], Sidx, optInTimePeriod);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
                            if (stA.OutRange.BegIdx != begS || stA.OutRange.Count != nbS) rangeOk = false;
                        } catch (ArgumentException) { rangeOk = false; if (diag.Length == 0) diag = ",\"anchoredOpenRejected\":1"; }
                    }
                }
            }
        }
        string extra = ",\"updAlloc\":" + updAlloc;
        return "{\"retCode\":0,\"beg\":" + beg + ",\"nb\":" + nb + ",\"legs\":" + legs + ",\"fill_checked\":" + fillChecked + ",\"fill_ok\":" + (fillOk ? 1 : 0) + ",\"ufill_checked\":" + ufillChecked + ",\"ufill_ok\":" + (ufillOk ? 1 : 0) + ",\"range_checked\":" + rangeChecked + ",\"range_legs\":" + rangeLegs + ",\"range_sites\":" + rangeSites + ",\"range_sites_n\":4,\"range_ok\":" + (rangeOk ? 1 : 0) + ",\"ok\":" + ((allOk && fillOk && ufillOk && rangeOk) ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + extra + diag + "}";
    }

    static string Sv_CDL2CROWS(JsonElement req) {
        int svShape = GetInt(req, "gen_shape", 0);
        int svSeed = GetInt(req, "gen_seed", 0);
        int svN = GetInt(req, "gen_n", 0);
        if (svN < 2) svN = 2;
        if (svN > 256) svN = 256;
        int svK = GetInt(req, "unstablePeriod", 0);
        int svCompat = GetInt(req, "compatibility", 0);
        if (svCompat != 0) {
            return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
        }
        int candleLegs = GetInt(req, "candleLegs", 0);
        double[] fz_o = new double[svN];
        double[] fz_h = new double[svN];
        double[] fz_l = new double[svN];
        double[] fz_c = new double[svN];
        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        int[] b0 = new int[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        int candleMutRan = 0;
        int candleMutMoved = 0;
        long zsignMut = 0;
        int rounds = (candleLegs != 0) ? 4 : 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            cb = SvApplyCandleRound(cb, rd);
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.CDL2CROWS_Impl(0, svN - 1, fz_o, fz_h, fz_l, fz_c, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.CDL2CROWS_Lookback();
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.CDL2CROWS_Open(fz_o, fz_h, fz_l, fz_c); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                if (!openRejects) allOk = false;
                if (rd + 1 < rounds) continue;
                return "{\"retCode\":" + (int)rc + ",\"legs\":" + legs + ",\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (allOk ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + "}";
            }
            fillChecked = 1;
            try {
                int[] f0 = new int[svN];
                Array.Fill(f0, (int)-987654321);
                Core.CDL2CROWS_Stream _fh = c2.CDL2CROWS_OpenAndFill(fz_o, fz_h, fz_l, fz_c, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (f0[bi] != b0[bi]) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (int)-987654321) fillOk = false;
                }
                /* R2: aliasing cross product -- every real output x every input,
                   then every same-typed output pair. Each must throw. */
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.CDL2CROWS_Stream st;
                try { st = c2.CDL2CROWS_Open(fz_o[..p], fz_h[..p], fz_l[..p], fz_c[..p]); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                int v0 = st.Value;
                if (v0 != b0[p - 1 - beg]) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        int pk = st.Peek(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                        int up = st.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                        if (pk != up) peekAll = false;
                        _ = st.Peek(fz_o[t - 1], fz_h[t - 1], fz_l[t - 1], fz_c[t - 1]);
                        int vc = st.Value;
                        if (vc != up) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (up != b0[t - beg]) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + b0[t - beg] + "\",\"streamv\":\"" + up + "\""; }
                    } else {
                        int up = st.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                        if (up != b0[t - beg]) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + b0[t - beg] + "\",\"streamv\":\"" + up + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.CDL2CROWS_Stream stu = c2.CDL2CROWS_Open(fz_o[..p], fz_h[..p], fz_l[..p], fz_c[..p]);
                        OutRange ur0 = stu.OutRange;
                        int[] u0 = new int[svN];
                        Array.Fill(u0, (int)-987654321);
                        stu.UpdateAndFill(fz_o.AsSpan(p, 0), fz_h.AsSpan(p, 0), fz_l.AsSpan(p, 0), fz_c.AsSpan(p, 0), u0);
                        try { stu.UpdateAndFill(fz_o.AsSpan(p), fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), new int[0]); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_o.AsSpan(p), fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), u0);
                        for (int t = p; t < svN; t++) if (u0[t - p] != b0[t - beg]) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (int)-987654321) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.CDL2CROWS_Stream sA = c2.CDL2CROWS_Open(fz_o[..p0], fz_h[..p0], fz_l[..p0], fz_c[..p0]);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                        Core.CDL2CROWS_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            int uA = sA.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                            int uB = sB.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                            if (uA != uB || uA != b0[t - beg]) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.CDL2CROWS_Stream sQ = c2.CDL2CROWS_Open(fz_o[..pa], fz_h[..pa], fz_l[..pa], fz_c[..pa]);
                        long sink = 0L;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            int uq = sQ.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                            sink += uq;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            {
                int pc = lb + 1 + seedShift;
                if (pc <= svN - 1) {
                    CandleSetting[] svSaved = (CandleSetting[])c2.candleSettings.Clone();
                    int[] m0 = new int[svN];
                    try {
                        Core.CDL2CROWS_Stream sC = c2.CDL2CROWS_Open(fz_o[..pc], fz_h[..pc], fz_l[..pc], fz_c[..pc]);
                        SvMutateLiveCandles(c2);
                        candleMutRan = 1;
                        int mBeg = 0, mNb = 0;
                        RetCode mrc;
                        try { mrc = c2.CDL2CROWS_Impl(0, svN - 1, fz_o, fz_h, fz_l, fz_c, out mBeg, out mNb, m0); }
                        catch (Exception _mve) when (_mve is ITaLibFailure) { mrc = ((ITaLibFailure)_mve).RetCode; mBeg = 0; mNb = 0; }
                        if (mrc != RetCode.Success || mNb != nb || mBeg != beg) candleMutMoved = 1;
                        else {
                            for (int bi = 0; bi < nb; bi++) if (m0[bi] != b0[bi]) candleMutMoved = 1;
                        }
                        for (int t = pc; t < svN; t++) {
                            int uC = sC.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                            if (uC != b0[t - beg]) { allOk = false; if (diag.Length == 0) diag = ",\"candleSnapshotLeaked\":" + t + ",\"badOut\":0"; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"candleMutOpenReject\":1"; }
                    catch (IndexOutOfRangeException) { allOk = false; if (diag.Length == 0) diag = ",\"candleSnapshotLeakedThrow\":1"; }
                    finally { SvRestoreLiveCandles(c2, svSaved); }
