                    int[] m0 = new int[svN];
                    try {
                        Core.CDLDOJISTAR_Stream sC = c2.CDLDOJISTAR_Open(fz_o[..pc], fz_h[..pc], fz_l[..pc], fz_c[..pc]);
                        SvMutateLiveCandles(c2);
