                        try {
                            Core.CDLDOJISTAR_Stream stA = c2.CDLDOJISTAR_OpenInternal(fz_o[..svN], fz_h[..svN], fz_l[..svN], fz_c[..svN], Sidx);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
