                    int[] m0 = new int[svN];
                    try {
                        Core.CDLLADDERBOTTOM_Stream sC = c2.CDLLADDERBOTTOM_Open(fz_o[..pc], fz_h[..pc], fz_l[..pc], fz_c[..pc]);
