                Core.CDLMATHOLD_Stream _fh = c2.CDLMATHOLD_OpenAndFill(fz_o, fz_h, fz_l, fz_c, optInPenetration, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
