                        else {
                            for (int bi = 0; bi < nb; bi++) if (m0[bi] != b0[bi]) candleMutMoved = 1;
                        }
                        for (int t = pc; t < svN; t++) {
                            int uC = sC.Update(fz_o[t], fz_h[t], fz_l[t], fz_c[t]);
                            if (uC != b0[t - beg]) { allOk = false; if (diag.Length == 0) diag = ",\"candleSnapshotLeaked\":" + t + ",\"badOut\":0"; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"candleMutOpenReject\":1"; }
                    catch (IndexOutOfRangeException) { allOk = false; if (diag.Length == 0) diag = ",\"candleSnapshotLeakedThrow\":1"; }
                    finally { SvRestoreLiveCandles(c2, svSaved); }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.CDLTHRUSTING_Open(fz_o[..lb], fz_h[..lb], fz_l[..lb], fz_c[..lb]); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
