                Core.CMF_Stream sD = c2.CMF_Open(fz_h, fz_l, fz_c, fz_v, int.MinValue);
                Core.CMF_Stream sE = c2.CMF_Open(fz_h, fz_l, fz_c, fz_v, 20);
                double vD = sD.Value;
                double vE = sE.Value;
                if (SvBne(vD, vE)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
