                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.CMF_Impl(Sidx, svN - 1, fz_h, fz_l, fz_c, fz_v, optInTimePeriod, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
