                try { _ = c2.MFI_OpenAndFill(fz_h, fz_l, fz_c, fz_v, optInTimePeriod, fz_h.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
