                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.NVI_Impl(Sidx, svN - 1, fz_c, fz_v, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
