                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, fz_l, f1); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inLow */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, fz_c, f1); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inClose */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, fz_h); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inHigh */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, fz_l); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inLow */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inClose */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, f0); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases output 0 */ }
                /* R2b: PARTIAL overlap -- only spans can express it, and it is
                   the only shape that separates Overlaps from identity. */
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0.AsSpan(0, svN - 1), f0.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/1 partially overlap (offset) */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0.AsSpan(0, svN - 1), f0.AsSpan(0, svN)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 0/1 partially overlap (same start, longer) */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, fz_h.AsSpan(1, svN - 1), f1); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
                try { _ = c2.STOCHF_OpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, fz_h.AsSpan(1, svN - 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
                if (p < lb + 1 + seedShift || p > svN - 1 || p == prevP) continue;
                prevP = p;
                Core.STOCHF_Stream st;
                try { st = c2.STOCHF_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInFastK_Period, optInFastD_Period, optInFastD_MAType); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
                Core.STOCHF_Value v0 = st.Value;
                if (SvXtierNe(v0.FastK, b0[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":0,\"where\":\"open\""; }
                if (SvXtierNe(v0.FastD, b1[p - 1 - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + (p - 1) + ",\"badOut\":1,\"where\":\"open\""; }
                for (int t = p; t < svN; t++) {
                    if (t % 7 == 0) {
                        Core.STOCHF_Value pk = st.Peek(fz_h[t], fz_l[t], fz_c[t]);
                        Core.STOCHF_Value up = st.Update(fz_h[t], fz_l[t], fz_c[t]);
                        if (SvBne(pk.FastK, up.FastK)) peekAll = false;
                        if (SvBne(pk.FastD, up.FastD)) peekAll = false;
                        _ = st.Peek(fz_h[t - 1], fz_l[t - 1], fz_c[t - 1]);
                        Core.STOCHF_Value vc = st.Value;
                        if (SvBne(vc.FastK, up.FastK)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvBne(vc.FastD, up.FastD)) { allOk = false; if (diag.Length == 0) diag = ",\"valueNeUpdate\":" + t; }
                        if (SvXtierNe(up.FastK, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.FastK).ToString("x16") + "\""; }
                        if (SvXtierNe(up.FastD, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":1,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b1[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.FastD).ToString("x16") + "\""; }
                    } else {
                        Core.STOCHF_Value up = st.Update(fz_h[t], fz_l[t], fz_c[t]);
                        if (SvXtierNe(up.FastK, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":0,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b0[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.FastK).ToString("x16") + "\""; }
                        if (SvXtierNe(up.FastD, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"badBar\":" + t + ",\"badOut\":1,\"batchv\":\"" + BitConverter.DoubleToInt64Bits(b1[t - beg]).ToString("x16") + "\",\"streamv\":\"" + BitConverter.DoubleToInt64Bits(up.FastD).ToString("x16") + "\""; }
                    }
                }
                if (allOk) {
                    rangeChecked = 1; rangeLegs++; rangeSites |= 2;
                    if (st.OutRange.BegIdx != beg || st.OutRange.Count != nb) rangeOk = false;
                }
            }
            {
                int p = lb + 1 + seedShift;
                if (p <= svN - 1) {
                    ufillChecked = 1;
                    try {
                        Core.STOCHF_Stream stu = c2.STOCHF_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInFastK_Period, optInFastD_Period, optInFastD_MAType);
                        OutRange ur0 = stu.OutRange;
                        double[] u0 = new double[svN];
                        Array.Fill(u0, (double)-1.2345678901234e300);
                        double[] u1 = new double[svN];
                        Array.Fill(u1, (double)-1.2345678901234e300);
                        stu.UpdateAndFill(fz_h.AsSpan(p, 0), fz_l.AsSpan(p, 0), fz_c.AsSpan(p, 0), u0, u1);
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), new double[0], u1); ufillOk = false; } catch (ArgumentException) { /* expected: output shorter than the run */ }
                        try { stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), fz_h.AsSpan(p), u1); ufillOk = false; } catch (ArgumentException) { /* expected: output overlaps input */ }
                        if (stu.OutRange.BegIdx != ur0.BegIdx || stu.OutRange.Count != ur0.Count) ufillOk = false;
                        stu.UpdateAndFill(fz_h.AsSpan(p), fz_l.AsSpan(p), fz_c.AsSpan(p), u0, u1);
                        for (int t = p; t < svN; t++) if (SvXtierNe(u0[t - p], b0[t - beg], ref zsign)) ufillOk = false;
                        for (int t = p; t < svN; t++) if (SvXtierNe(u1[t - p], b1[t - beg], ref zsign)) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u0[t] != (double)-1.2345678901234e300) ufillOk = false;
                        for (int t = svN - p; t < svN; t++) if (u1[t] != (double)-1.2345678901234e300) ufillOk = false;
                        rangeChecked = 1; rangeLegs++; rangeSites |= 4;
                        if (stu.OutRange.BegIdx != beg || stu.OutRange.Count != nb) { ufillOk = false; rangeOk = false; }
                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.STOCHF_Stream sA = c2.STOCHF_Open(fz_h[..p0], fz_l[..p0], fz_c[..p0], optInFastK_Period, optInFastD_Period, optInFastD_MAType);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                        Core.STOCHF_Stream sB = sA.Clone();
                        for (int t = mid; t < svN; t++) {
                            Core.STOCHF_Value uA = sA.Update(fz_h[t], fz_l[t], fz_c[t]);
                            Core.STOCHF_Value uB = sB.Update(fz_h[t], fz_l[t], fz_c[t]);
                            if (SvBne(uA.FastK, uB.FastK) || SvXtierNe(uA.FastK, b0[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                            if (SvBne(uA.FastD, uB.FastD) || SvXtierNe(uA.FastD, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
                    } catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"copyOpenReject\":1"; }
                }
            }
            {
                int pa = lb + 1 + seedShift;
                if (pa <= svN - 1) {
                    try {
                        Core.STOCHF_Stream sQ = c2.STOCHF_Open(fz_h[..pa], fz_l[..pa], fz_c[..pa], optInFastK_Period, optInFastD_Period, optInFastD_MAType);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            Core.STOCHF_Value uq = sQ.Update(fz_h[t], fz_l[t], fz_c[t]);
                            sink += uq.FastK;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
                        if (ad != 0) { allOk = false; if (diag.Length == 0) diag = ",\"updAllocBytes\":" + ad; }
                    } catch (ArgumentException) { /* open rejects here -- nothing to measure */ }
                }
            }
            if (lb >= 1 && lb < svN) {
                try { _ = c2.STOCHF_Open(fz_h[..lb], fz_l[..lb], fz_c[..lb], optInFastK_Period, optInFastD_Period, optInFastD_MAType); allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryAccepted\":1"; }
                catch (InsufficientHistoryException) { /* expected, typed */ }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"shortHistoryWrongType\":1"; }
            }
            try {
                Core.STOCHF_Stream sD = c2.STOCHF_Open(fz_h, fz_l, fz_c, int.MinValue, int.MinValue, optInFastD_MAType);
                Core.STOCHF_Stream sE = c2.STOCHF_Open(fz_h, fz_l, fz_c, 5, 3, optInFastD_MAType);
                Core.STOCHF_Value vD = sD.Value;
                Core.STOCHF_Value vE = sE.Value;
                if (SvBne(vD.FastK, vE.FastK)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
                if (SvBne(vD.FastD, vE.FastD)) { allOk = false; if (diag.Length == 0) diag = ",\"minValueDefault\":1"; }
            } catch (ArgumentException) { /* defaults need more history than svN -- skip */ }
            {
                int Sidx = lb + (svN - lb) / 3;
                if (Sidx > lb && Sidx < svN - 1) {
                    int begS = 0, nbS = 0;
                    RetCode rcS;
                    try { rcS = c2.STOCHF_Impl(Sidx, svN - 1, fz_h, fz_l, fz_c, optInFastK_Period, optInFastD_Period, optInFastD_MAType, out begS, out nbS, b0, b1); }
                    catch (Exception _sve) when (_sve is ITaLibFailure) { rcS = ((ITaLibFailure)_sve).RetCode; }
                    if (rcS == RetCode.Success && nbS > 0) {
                        try {
                            Core.STOCHF_Stream stA = c2.STOCHF_OpenInternal(fz_h[..svN], fz_l[..svN], fz_c[..svN], Sidx, optInFastK_Period, optInFastD_Period, optInFastD_MAType);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 8;
                            if (stA.OutRange.BegIdx != begS || stA.OutRange.Count != nbS) rangeOk = false;
                        } catch (ArgumentException) { rangeOk = false; if (diag.Length == 0) diag = ",\"anchoredOpenRejected\":1"; }
                    }
                }
            }
        }
        string extra = ",\"updAlloc\":" + updAlloc;
        return "{\"retCode\":0,\"beg\":" + beg + ",\"nb\":" + nb + ",\"legs\":" + legs + ",\"fill_checked\":" + fillChecked + ",\"fill_ok\":" + (fillOk ? 1 : 0) + ",\"ufill_checked\":" + ufillChecked + ",\"ufill_ok\":" + (ufillOk ? 1 : 0) + ",\"range_checked\":" + rangeChecked + ",\"range_legs\":" + rangeLegs + ",\"range_sites\":" + rangeSites + ",\"range_sites_n\":4,\"range_ok\":" + (rangeOk ? 1 : 0) + ",\"ok\":" + ((allOk && fillOk && ufillOk && rangeOk) ? 1 : 0) + ",\"peek_ok\":" + (peekAll ? 1 : 0) + ",\"benign\":" + zsign + extra + diag + "}";
    }

    static string Sv_STOCHRSI(JsonElement req) {
        int svShape = GetInt(req, "gen_shape", 0);
        int svSeed = GetInt(req, "gen_seed", 0);
        int svN = GetInt(req, "gen_n", 0);
        if (svN < 2) svN = 2;
        if (svN > 256) svN = 256;
        int svK = GetInt(req, "unstablePeriod", 0);
        int svCompat = GetInt(req, "compatibility", 0);
        if (svCompat != 0) {
            return "{\"error\":\"csharp has no compatibility API (pinned to Default)\"}";
        }
        int optInTimePeriod = GetInt(req, "optInTimePeriod", 14);
        int optInFastK_Period = GetInt(req, "optInFastK_Period", 5);
        int optInFastD_Period = GetInt(req, "optInFastD_Period", 3);
        int _raw_optInFastD_MAType = GetInt(req, "optInFastD_MAType", 0);
        MAType optInFastD_MAType = (MAType)_raw_optInFastD_MAType;
        double[] fz_o = new double[svN];
        double[] fz_h = new double[svN];
        double[] fz_l = new double[svN];
        double[] fz_c = new double[svN];
        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        double[] b0 = new double[svN];
        double[] b1 = new double[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        Core c0 = new Core();
        if (!Enum.IsDefined(optInFastD_MAType)) {
            bool eOpen, eFill;
            try { _ = c0.STOCHRSI_Open(fz_c, optInTimePeriod, optInFastK_Period, optInFastD_Period, optInFastD_MAType); eOpen = false; }
            catch (ArgumentException) { eOpen = true; }
            double[] f0 = new double[svN];
            Array.Fill(f0, (double)-1.2345678901234e300);
            double[] f1 = new double[svN];
            Array.Fill(f1, (double)-1.2345678901234e300);
            try { _ = c0.STOCHRSI_OpenAndFill(fz_c, optInTimePeriod, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, f1); eFill = false; }
            catch (ArgumentException) { eFill = true; }
            bool eOk = eOpen && eFill;
            return "{\"retCode\":2,\"legs\":0,\"nb\":0,\"openRejects\":" + (eOk ? 1 : 0) + ",\"enumRejects\":" + ((eOpen ? 1 : 0) + (eFill ? 1 : 0)) + ",\"ok\":" + (eOk ? 1 : 0) + ",\"peek_ok\":1}";
        }
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            cb = cb.UnstablePeriod((FuncUnstId)23, svK);
            cb = cb.UnstablePeriod((FuncUnstId)14, svK);
            cb = cb.UnstablePeriod((FuncUnstId)13, svK);
            cb = cb.UnstablePeriod((FuncUnstId)5, svK);
            cb = cb.UnstablePeriod((FuncUnstId)21, svK);
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.STOCHRSI_Impl(0, svN - 1, fz_c, optInTimePeriod, optInFastK_Period, optInFastD_Period, optInFastD_MAType, out beg, out nb, b0, b1); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.STOCHRSI_Lookback(optInTimePeriod, optInFastK_Period, optInFastD_Period, optInFastD_MAType);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
                try { _ = c2.STOCHRSI_Open(fz_c, optInTimePeriod, optInFastK_Period, optInFastD_Period, optInFastD_MAType); openRejects = false; }
                catch (ArgumentException) { openRejects = true; }
                return "{\"retCode\":" + (int)rc + ",\"legs\":0,\"nb\":" + nb + ",\"openRejects\":" + (openRejects ? 1 : 0) + ",\"ok\":" + (openRejects ? 1 : 0) + ",\"peek_ok\":1}";
            }
            fillChecked = 1;
            try {
                double[] f0 = new double[svN];
                Array.Fill(f0, (double)-1.2345678901234e300);
                double[] f1 = new double[svN];
                Array.Fill(f1, (double)-1.2345678901234e300);
                Core.STOCHRSI_Stream _fh = c2.STOCHRSI_OpenAndFill(fz_c, optInTimePeriod, optInFastK_Period, optInFastD_Period, optInFastD_MAType, f0, f1);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
                if (_fr.BegIdx != beg || _fr.Count != nb) rangeOk = false;
                if (_fr.BegIdx != beg || _fr.Count != nb) fillOk = false;
                else {
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f0[bi], b0[bi], ref zsign)) fillOk = false;
                    for (int bi = 0; bi < nb; bi++) if (SvXtierNe(f1[bi], b1[bi], ref zsign)) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f1[bi] != (double)-1.2345678901234e300) fillOk = false;
                }
