                    RetCode rcS;
                    try { rcS = c2.ULTOSC_Impl(Sidx, svN - 1, fz_h, fz_l, fz_c, optInTimePeriod1, optInTimePeriod2, optInTimePeriod3, out begS, out nbS, b0); }
