                prevP = p;
                Core.WILLR_Stream st;
                try { st = c2.WILLR_Open(fz_h[..p], fz_l[..p], fz_c[..p], optInTimePeriod); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
